def to_csv_row(fields):
    row = ""
    first = True
    for field in fields:
        if first:
            row = row + field
            first = False
        else:
            row = row + "," + field
    return row

if __name__ == "__main__":
    assert to_csv_row(["a", "b", "c"]) == "a,b,c"
    assert to_csv_row(["solo"]) == "solo"
    print("behavior preserved")
